### 📄 1. `deploy-commands.js` – Đăng ký lệnh gạch chéo

```js
const { REST, Routes } = require('discord.js');
const { Client, Collection, GatewayIntentBits } = require('discord.js');
const { token, clientId, guildId } = require('./config.json'); // Thay bằng token, client ID, guild ID của bạn

const commands = [
  {
    name: 'ban',
    description: 'Cấm một thành viên khỏi máy chủ',
    options: [
      {
        name: 'user',
        type: 6, // USER type
        description: 'Người dùng cần cấm',
        required: true,
      },
      {
        name: 'reason',
        type: 3, // STRING type
        description: 'Lý do cấm',
        required: false,
      },
    ],
  },
];

const rest = new REST({ version: '10' }).setToken(token);

(async () => {
  try {
    console.log('Bắt đầu đăng ký lệnh gạch chéo (/).');

    await rest.put(
      Routes.applicationGuildCommands(clientId, guildId),
      { body: commands }
    );

    console.log('Đăng ký thành công 1 lệnh (/ban)!');
  } catch (error) {
    console.error(error);
  }
})();
```

> 🔐 Tạo file `config.json`:
```json
{
  "token": "YOUR_BOT_TOKEN_HERE",
  "clientId": "YOUR_BOT_CLIENT_ID",
  "guildId": "YOUR_SERVER_GUILD_ID"
}
```

