### 📄 2. `index.js` – Xử lý lệnh `/ban`

```js
const { Client, Collection, GatewayIntentBits, PermissionsBitField } = require('discord.js');
const { token, clientId, guildId } = require('./config.json');

const client = new Client({
  intents: [
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildMessages,
    GatewayIntentBits.DirectMessages
  ]
});

client.commands = new Collection();

client.once('ready', () => {
  console.log(`Bot đã sẵn sàng: ${client.user.tag}`);
});

client.on('interactionCreate', async interaction => {
  if (!interaction.isChatInputCommand()) return;

  if (interaction.commandName === 'ban') {
    // Kiểm tra quyền
    if (!interaction.member.permissions.has(PermissionsBitField.Flags.BanMembers)) {
      return interaction.reply({ content: '❌ Bạn không có quyền cấm thành viên!', ephemeral: true });
    }

    const user = interaction.options.getUser('user');
    const reason = interaction.options.getString('reason') || 'Không có lý do';

    const member = await interaction.guild.members.fetch(user.id).catch(() => null);

    // Kiểm tra xem có thể cấm người dùng không
    if (!member) {
      return interaction.reply({ content: '❌ Không tìm thấy thành viên này trong máy chủ.', ephemeral: true });
    }

    if (!member.bannable) {
      return interaction.reply({ content: '❌ Bot không thể cấm thành viên này (quyền quá cao hoặc đồng cấp).', ephemeral: true });
    }

    // Thực hiện cấm
    await member.ban({ reason })
      .then(() => {
        interaction.reply({ content: `✅ Đã cấm ${user.tag} khỏi máy chủ.\nLý do: ${reason}` });
      })
      .catch(err => {
        console.error(err);
        interaction.reply({ content: '❌ Đã xảy ra lỗi khi cấm thành viên.', ephemeral: true });
      });
  }
});

client.login(token);
```

