## 🛠️ 3. Cấu hình Cypress (`cypress.config.js`)

```js
const { defineConfig } = require('cypress');

module.exports = defineConfig({
  e2e: {
    setupNodeEvents(on, config) {
      // Cấu hình chụp ảnh màn hình
      on('before:browser:launch', (browser, launchOptions) => {
        if (browser.name === 'chrome' && browser.family === 'chromium') {
          launchOptions.args.push('--disable-dev-shm-usage');
          launchOptions.args.push('--no-sandbox');
          return launchOptions;
        }
      });

      // Ghi log chụp ảnh khi chạy test
      on('task', {
        log(message) {
          console.log(message);
          return null;
        },
      });
    },
    baseUrl: 'http://localhost:3000', // Thay bằng URL ứng dụng của bạn
    video: true,
    screenshotOnRunFailure: true,     // Tự động chụp khi test fail
    videosFolder: 'cypress/videos',
    screenshotsFolder: 'cypress/screenshots',
    defaultCommandTimeout: 10000,
    retries: {
      runMode: 1, // Retry 1 lần nếu test fail trong môi trường CI
      openMode: 0,
    },
  },
});
```

