## 🖼️ 4. Viết test với chụp ảnh màn hình

### `cypress/e2e/login.cy.js`

```js
describe('Login Test with Screenshot', () => {
  beforeEach(() => {
    cy.visit('/login'); // Giả sử có trang login
  });

  it('should fail and capture screenshot', () => {
    cy.get('#email').type('user@example.com');
    cy.get('#password').type('wrongpassword');
    cy.get('form').submit();

    // Chụp ảnh khi có lỗi (sẽ tự động chụp nếu test fail)
    cy.get('.error-message').should('contain', 'Invalid credentials');

    // Chụp ảnh thủ công
    cy.screenshot('login-failed'); // Lưu vào `cypress/screenshots/login-failed.png`
  });

  it('should succeed and capture screenshot', () => {
    cy.get('#email').type('admin@example.com');
    cy.get('#password').type('correctpassword');
    cy.get('form').submit();

    cy.url().should('include', '/dashboard');
    cy.screenshot('login-success');
  });
});
```

