Dưới đây là một hàm C++ cơ bản để chuyển đổi một chuỗi Markdown đơn giản sang HTML. Hàm này sử dụng tham chiếu đến `const std::string&` để tránh sao chép không cần thiết và trả về một `std::string` chứa nội dung HTML tương ứng.

Chức năng hỗ trợ:
- In đậm: `**text**` → `<strong>text</strong>`
- In nghiêng: `*text*` → `<em>text</em>`
- Tiêu đề từ `#` đến `###`: `# Tiêu đề` → `<h1>Tiêu đề</h1>`
- Dòng ngang: `---` hoặc `***` → `<hr/>`
- Dòng đoạn văn: văn bản thông thường → `<p>văn bản</p>`

```cpp
#include <string>
#include <regex>
#include <sstream>
#include <vector>

std::string markdown_to_html(const std::string& markdown) {
    std::istringstream iss(markdown);
    std::ostringstream oss;
    std::string line;

    auto process_inline = [](std::string text) -> std::string {
        // In đậm: **text** hoặc __text__
        text = std::regex_replace(text, std::regex(R"(\\*\\*(.*?)\\*\\*)"), R"(<strong>$1</strong>)");
        text = std::regex_replace(text, std::regex(R"(__(.*?)__)"), R"(<strong>$1</strong>)");

        // In nghiêng: *text* hoặc _text_
        text = std::regex_replace(text, std::regex(R"(\\*(.*?)\\*)"), R"(<em>$1</em>)");
        text = std::regex_replace(text, std::regex(R"(_(.*?)_)"), R"(<em>$1</em>)");

        return text;
    };

    bool in_paragraph = false;

    while (std::getline(iss, line)) {
        // Xóa khoảng trắng đầu cuối
        line = std::regex_replace(line, std::regex(R"(^\s+|\s+$)"), "");

        // Tiêu đề: #, ##, ###
        if (std::regex_match(line, std::regex(R"(^(#{1,3})\s+.*)"))) {
            if (in_paragraph) {
                oss << "</p>\n";
                in_paragraph = false;
            }
            std::smatch match;
            std::regex_search(line, match, std::regex(R"(^(#{1,3})\s+(.*))"));
            int level = match[1].str().size();
            std::string content = process_inline(match[2].str());
            oss << "<h" << level << ">" << content << "</h" << level << ">\n";
        }
        // Dòng ngang
        else if (std::regex_match(line, std::regex(R"(^(\*{3}|-{3})$)"))) {
            if (in_paragraph) {
                oss << "</p>\n";
                in_paragraph = false;
            }
            oss << "<hr/>\n";
        }
        // Dòng trống: kết thúc đoạn văn
        else if (line.empty()) {
            if (in_paragraph) {
                oss << "</p>\n";
                in_paragraph = false;
            }
        }
        // Đoạn văn
        else {
            if (!in_paragraph) {
                oss << "<p>";
                in_paragraph = true;
            } else {
                oss << " ";  // thêm khoảng trắng giữa các dòng trong cùng đoạn
            }
            oss << process_inline(line);
        }
    }

    // Đóng thẻ p nếu đang trong đoạn
    if (in_paragraph) {
        oss << "</p>\n";
    }

    return oss.str();
}
```

### Ví dụ sử dụng:

```cpp
#include <iostream>

int main() {
    std::string md = R"(
# Tiêu đề lớn
Đây là đoạn văn đầu tiên với *in nghiêng* và **in đậm**.

## Tiêu đề nhỏ
Dòng này có _in nghiêng_ và __in đậm__.
---
Đây là đoạn cuối.
)";

    std::string html = markdown_to_html(md);
    std::cout << html << std::endl;

    return 0;
}
```

### Output (gần đúng):
```html
<h1>Tiêu đề lớn</h1>
<p>Đây là đoạn văn đầu tiên với <em>in nghiêng</em> và <strong>in đậm</strong>.</p>
<h2>Tiêu đề nhỏ</h2>
<p>Dòng này có <em>in nghiêng</em> và <strong>in đậm</strong>.</p>
<hr/>
<p>Đây là đoạn cuối.</p>
```

